 vi.mock('@salesforce/retail-react-app/app/hooks/use-intersection-observer', () => ({
-  default: () => false,
+  default: mockUseIntersectionObserver,
 }));

 vi.mock('@salesforce/retail-react-app/app/hooks/use-wish-list', () => ({
@@ -377,3 +390,81 @@ describe('RecommendedProducts — Recently Viewed branch (SFCC-83/84, build plan
     expect(railProps.seeAllLabel).toBeUndefined();
   });
 });
+
+// PostBuild fix round, Fix 1/Fix 3 (2026-09-15). No pre-existing test in this file exercised the
+// impression-tracking effect at all before this: `isOnScreen` was unconditionally stubbed `false`
+// everywhere above (see that mock's own comment), so `if (isOnScreen && recommendations?.recs)`
+// never ran its body in any existing test. Both tests below override it to `true` for one render
+// via `mockUseIntersectionObserver.mockReturnValueOnce(true)` — a per-test override that leaves
+// every test above completely unaffected (the mock's own default return stays `false`).
+describe('RecommendedProducts — impression tracking (PostBuild fix round, Fix 1, 2026-09-15)', () => {
+  test('Recently-Viewed: when every rec fails to map, no impression is reported at all', () => {
+    // The exact bug Fix 1 closes: every one of this shopper's recently-viewed products fails
+    // `selectRecentlyViewedCard`'s null-gate (e.g. no usable name/image), so the rail correctly
+    // renders nothing — but before this fix, the impression-tracking effect ran ahead of that
+    // filtering and still reported every raw id in `recommendations.recs` as "viewed": false signal
+    // into Einstein/DataCloud's own feedback loop, with nothing on screen to indicate it happened.
+    //
+    // Verified directly, not just asserted (this codebase's own prove-don't-assert discipline —
+    // matches recentlyViewed/index.test.tsx's own "all-stale-history gate" test): temporarily
+    // reverting index.tsx's impression-tracking effect back to its pre-Fix-1 form (mapping
+    // `recommendations.recs` directly, with no recommender branch) makes this exact test fail —
+    // both `mockSendViewReco` and `mockSendViewRecommendations` are called, with the two ids that
+    // never actually rendered — and restoring Fix 1 makes it pass again.
+    const mockSendViewReco = vi.fn();
+    mockUseEinstein.mockReturnValue({
+      isLoading: false,
+      recommendations: buildRecentlyViewedRecommendations(mockRecentlyViewedProducts),
+      getZoneRecommendations: vi.fn(),
+      getRecommendations: vi.fn(),
+      sendClickReco: vi.fn(),
+      sendViewReco: mockSendViewReco,
+    });
+    // Both fixture products fail the mapper's own hard gate — the scenario Fix 1 exists for.
+    mockSelectRecentlyViewedCard.mockReturnValue(null);
+    mockUseIntersectionObserver.mockReturnValueOnce(true);
+
+    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, title: 'Recently Viewed' });
+
+    // The mapping was attempted (proves this is "attempted and filtered", not "never ran") ...
+    expect(mockSelectRecentlyViewedCard).toHaveBeenCalled();
+    // ... but nothing survived it, so no impression was reported at all.
+    expect(mockSendViewReco).not.toHaveBeenCalled();
+    expect(mockSendViewRecommendations).not.toHaveBeenCalled();
+  });
+
+  test('any other recommender still reports the full raw recs list on impression, unchanged', () => {
+    // Confirms Fix 1's recommender branch is genuinely additive, not a regression for the other
+    // four recommenders: a non-Recently-Viewed recommender has no `selectRecentlyViewedCard`
+    // filtering step in this component at all, so its reported id list must still be the full, raw
+    // `recommendations.recs` mapped straight to `{ id }` — the exact pre-Fix-1 expression, now the
+    // untouched `else` branch of index.tsx's own `ids` ternary.
+    const mockSendViewReco = vi.fn();
+    const otherRecommendations = {
+      recommenderName: 'might-also-like-einstein',
+      recoUUID: 'test-other-reco-uuid',
+      displayMessage: 'You Might Also Like',
+      recs: [
+        { id: 'other-1', name: 'Recommended One' },
+        { id: 'other-2', name: 'Recommended Two' },
+      ],
+    };
+    mockUseEinstein.mockReturnValue({
+      isLoading: false,
+      recommendations: otherRecommendations,
+      getZoneRecommendations: vi.fn(),
+      getRecommendations: vi.fn(),
+      sendClickReco: vi.fn(),
+      sendViewReco: mockSendViewReco,
+    });
+    mockUseIntersectionObserver.mockReturnValueOnce(true);
+
+    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE });
+
+    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
+    const expectedIds = [{ id: 'other-1' }, { id: 'other-2' }];
+    const expectedRecoMeta = { recommenderName: 'might-also-like-einstein', __recoUUID: 'test-other-reco-uuid' };
+    expect(mockSendViewReco).toHaveBeenCalledWith(expectedRecoMeta, expectedIds);
+    expect(mockSendViewRecommendations).toHaveBeenCalledWith(expectedRecoMeta, expectedIds);
+  });
+});

