1	/**
2	 * SFCC-83/84 build plan step E1 — asserts only this component's own branch-selection contract
3	 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given a `recommender` and
4	 * `useEinstein()`'s own `recommendations`, does it render `ZimmRecentlyViewedRail`,
5	 * `ProductScroller`, or nothing at all. `ZimmRecentlyViewedRail`, `ProductScroller`, and
6	 * `selectRecentlyViewedCard` are all mocked at the smallest surface — their own internals already
7	 * have their own coverage elsewhere (`zimmRecentlyViewedRail/index.test.tsx`,
8	 * `recentlyViewedCard.test.ts`; base `ProductScroller` is untouched vendor code).
9	 *
10	 * **Rewritten for build plan step E1** — the interim mechanism's own hook mocks are gone (both
11	 * hooks are deleted in build plan step E4); every Recently-Viewed test case below now drives its
12	 * scenario entirely through the already-present `mockUseEinstein`, matching the exact pattern the
13	 * "any other recommender" test already used before this rewrite. Product fixtures use a real `id`
14	 * field (`RecentlyViewedProduct`, `recentlyViewedCard.ts`'s own alias for
15	 * `ShopperProductsTypes.Product`) since that is what a hydrated Einstein rec looks like by the
16	 * time this component reads it (see index.tsx's own module docblock, point 2).
17	 */
18	import React from 'react';
19	import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
20	import { render, screen } from '@testing-library/react';
21	import { MemoryRouter } from 'react-router-dom';
22	import { ChakraProvider } from '@chakra-ui/react';
23	import { IntlProvider } from 'react-intl';
24	import { EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
25	import theme from 'app/theme';
26	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
27	import { selectRecentlyViewedCard, type RecentlyViewedProduct } from '../../utils/recentlyViewedCard';
28	import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
29	import RecommendedProducts, { type RecommendedProductsProps } from '.';
30	
31	// Smallest-surface mocks throughout — see module docblock above for why each of these is safe to
32	// stub rather than exercise for real in this file.
33	
34	// Hoisted so the mock factories below (which vi.mock hoists above these imports) can reference
35	// them — a plain `const` here would not yet be initialised at that point. Matches the established
36	// pattern at useWishlistAuthDrawer.test.tsx:17-19. Added for Fix 3 (PostBuild fix round,
37	// 2026-09-15): both need to be one stable reference the new impression-tracking tests below can
38	// assert on / override per-test, rather than a fresh closure invented on every hook call.
39	const { mockSendViewRecommendations, mockUseIntersectionObserver } = vi.hoisted(() => ({
40	  mockSendViewRecommendations: vi.fn(),
41	  mockUseIntersectionObserver: vi.fn(() => false),
42	}));
43	
44	vi.mock('@salesforce/retail-react-app/app/hooks/use-einstein', () => ({
45	  default: vi.fn(),
46	}));
47	
48	vi.mock('@salesforce/retail-react-app/app/hooks/use-datacloud', () => ({
49	  default: () => ({ sendViewRecommendations: mockSendViewRecommendations }),
50	}));
51	
52	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-customer', () => ({
53	  useCurrentCustomer: () => ({ data: { customerId: 'test-customer-id' } }),
54	}));
55	
56	// Real use-intersection-observer.js already degrades to `true` under jsdom (no global
57	// IntersectionObserver), but stubbed anyway per this step's own brief, for a deterministic
58	// `isOnScreen` this file doesn't otherwise need to reason about. Still defaults to `false`
59	// unconditionally — behaviourally unchanged from before — wrapped in the hoisted `vi.fn()` above
