/**
 * SFCC-83/84 build plan step E1 — asserts only this component's own branch-selection contract
 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given a `recommender` and
 * `useEinstein()`'s own `recommendations`, does it render `ZimmRecentlyViewedRail`,
 * `ProductScroller`, or nothing at all. `ZimmRecentlyViewedRail`, `ProductScroller`, and
 * `selectRecentlyViewedCard` are all mocked at the smallest surface — their own internals already
 * have their own coverage elsewhere (`zimmRecentlyViewedRail/index.test.tsx`,
 * `recentlyViewedCard.test.ts`; base `ProductScroller` is untouched vendor code).
 *
 * **Rewritten for build plan step E1** — the interim mechanism's own hook mocks are gone (both
 * hooks are deleted in build plan step E4); every Recently-Viewed test case below now drives its
 * scenario entirely through the already-present `mockUseEinstein`, matching the exact pattern the
 * "any other recommender" test already used before this rewrite. Product fixtures use a real `id`
 * field (`RecentlyViewedProduct`, `recentlyViewedCard.ts`'s own alias for
 * `ShopperProductsTypes.Product`) since that is what a hydrated Einstein rec looks like by the
 * time this component reads it (see index.tsx's own module docblock, point 2).
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
import theme from 'app/theme';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import { selectRecentlyViewedCard, type RecentlyViewedProduct } from '../../utils/recentlyViewedCard';
import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
import RecommendedProducts, { type RecommendedProductsProps } from '.';

// Smallest-surface mocks throughout — see module docblock above for why each of these is safe to
// stub rather than exercise for real in this file.

// Hoisted so the mock factories below (which vi.mock hoists above these imports) can reference
// them — a plain `const` here would not yet be initialised at that point. Matches the established
// pattern at useWishlistAuthDrawer.test.tsx:17-19. Added for Fix 3 (PostBuild fix round,
// 2026-09-15): both need to be one stable reference the new impression-tracking tests below can
// assert on / override per-test, rather than a fresh closure invented on every hook call.
const { mockSendViewRecommendations, mockUseIntersectionObserver } = vi.hoisted(() => ({
  mockSendViewRecommendations: vi.fn(),
  mockUseIntersectionObserver: vi.fn(() => false),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-einstein', () => ({
  default: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-datacloud', () => ({
  default: () => ({ sendViewRecommendations: mockSendViewRecommendations }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-customer', () => ({
  useCurrentCustomer: () => ({ data: { customerId: 'test-customer-id' } }),
}));

// Real use-intersection-observer.js already degrades to `true` under jsdom (no global
// IntersectionObserver), but stubbed anyway per this step's own brief, for a deterministic
// `isOnScreen` this file doesn't otherwise need to reason about. Still defaults to `false`
// unconditionally — behaviourally unchanged from before — wrapped in the hoisted `vi.fn()` above
// only so the impression-tracking tests (Fix 3, PostBuild fix round) can override it to `true` for
// one render at a time via `mockReturnValueOnce`, without touching any other test in this file.
vi.mock('@salesforce/retail-react-app/app/hooks/use-intersection-observer', () => ({
  default: mockUseIntersectionObserver,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-wish-list', () => ({
  useWishList: () => ({ data: undefined }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
  useToast: () => vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-navigation', () => ({
  default: () => vi.fn(),
}));

// `buildUrl` is the one piece of this hook the See-Full-History link actually uses
// (site/locale-prefixing `RECENTLY_VIEWED_ROUTE`); a fixed non-default-site prefix here proves
// the link is correctly site-prefixed on a non-default storefront without needing the real
// multi-site provider context.
vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: () => ({ buildUrl: (path: string) => `/en-GB${path}` }),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useShopperCustomersMutation: () => ({ mutateAsync: vi.fn() }),
}));

// ProductScroller is a real `forwardRef` component (product-scroller/index.jsx) — mocked as one
// too, rather than a plain function, so `<ProductScroller ref={ref} .../>` doesn't trip React's
// "function components cannot be given refs" warning for no reason.
vi.mock('@salesforce/retail-react-app/app/components/product-scroller', () => ({
  default: React.forwardRef(function ProductScrollerStub(_props: unknown, ref: React.Ref<HTMLDivElement>) {
    return <div ref={ref} data-testid="product-scroller-stub" />;
  }),
}));

// Relative paths matching index.tsx's own imports exactly — see overrideStyling.md's
// "Importing an already-overridden component" doctrine cited there.
vi.mock('../ui-kits/organisms/zimmRecentlyViewedRail', () => ({
  ZimmRecentlyViewedRail: vi.fn(() => <div data-testid="zimm-recently-viewed-rail-stub" />),
}));

vi.mock('../../utils/recentlyViewedCard', () => ({
  selectRecentlyViewedCard: vi.fn(),
}));

// jsdom has no matchMedia implementation, and index.tsx's own `useRecentlyViewedRailVisibleCount`
// call (the See-Full-History trigger threshold) uses it internally via `useMediaQuery` — a
// per-file polyfill, not a change to the frozen vitest.setup.ts (Tier 1), matching the identical,
// already-established precedent at drawer-menu/index.test.tsx (Chakra Drawer's own
// useBreakpointValue usage). `matches: false` unconditionally is what makes both underlying
// `useMediaQuery` checks resolve to their smallest/mobile fallback in this environment — exactly
// what the See-Full-History tests below are written against.
beforeEach(() => {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addListener: vi.fn(),
      removeListener: vi.fn(),
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })),
  });
});

const mockUseEinstein = vi.mocked(useEinstein);
const mockSelectRecentlyViewedCard = vi.mocked(selectRecentlyViewedCard);
const mockZimmRecentlyViewedRail = vi.mocked(ZimmRecentlyViewedRail);

// Two products, deliberately different `id`s, so a mapping/filtering bug (wrong product picked,
// or the null-filter dropping the wrong entry) fails loudly rather than coincidentally matching —
// same doctrine recentlyViewedCard.test.ts documents as "G1". Shaped with a real `id` field
// (RecentlyViewedProduct — recentlyViewedCard.ts's own alias for
// `ShopperProductsTypes.Product`), matching what a hydrated Einstein rec looks like by the time
// this component reads it.
const mockRecentlyViewedProducts: RecentlyViewedProduct[] = [
  { id: 'rec-1', name: 'Product One' } as RecentlyViewedProduct,
  { id: 'rec-2', name: 'Product Two' } as RecentlyViewedProduct,
];

/** A real Recently-Viewed `useEinstein().recommendations` response shape, for the
 *  Recently-Viewed-branch tests below — `recommenderName` matches the actual recommender string
 *  (see index.tsx's own module docblock re: `PDP_RECENTLY_VIEWED`/`CART_RECENTLY_VIEWED`
 *  resolving identically). */
const buildRecentlyViewedRecommendations = (recs: RecentlyViewedProduct[]) => ({
  recommenderName: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED,
  recoUUID: 'test-rv-reco-uuid',
  displayMessage: 'Recently Viewed',
  recs,
});

// A real Einstein response shape — still used by the "any other recommender" test below, since
// only the Recently-Viewed branch's data source changed (build plan step E1).
const mockRecommendations = {
  recommenderName: 'might-also-like-einstein',
  recoUUID: 'test-reco-uuid',
  displayMessage: 'You Might Also Like',
  recs: [
    { productId: 'reco-1', name: 'Recommended One' },
    { productId: 'reco-2', name: 'Recommended Two' },
  ],
};

// `route` defaults to '/' — the component calls `useLocation()` unconditionally (Cart
// exclusion, 2026-09-10), so every render needs a Router ancestor regardless of what a given
// test actually asserts on. Only the dedicated Cart-exclusion test below passes a real route.
const renderRecommendedProducts = (props: Partial<RecommendedProductsProps> = {}, route = '/') =>
  render(
    <MemoryRouter initialEntries={[route]}>
      <IntlProvider locale="en-AU" messages={{}}>
        <ChakraProvider theme={theme}>
          <RecommendedProducts recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE} {...props} />
        </ChakraProvider>
      </IntlProvider>
    </MemoryRouter>,
  );

afterEach(() => {
  vi.clearAllMocks();
});

describe('RecommendedProducts — Recently Viewed branch (SFCC-83/84, build plan E1)', () => {
  test('recommender=PDP_RECENTLY_VIEWED with recs renders ZimmRecentlyViewedRail, not ProductScroller, and fires getRecommendations', () => {
    const mockGetRecommendations = vi.fn();
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: buildRecentlyViewedRecommendations(mockRecentlyViewedProducts),
      getZoneRecommendations: vi.fn(),
      getRecommendations: mockGetRecommendations,
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });
    // rec-2 deliberately maps to `null` (e.g. no usable image/name) — proves the branch's own
    // `.filter()` drops it instead of forwarding a null card or crashing. `href` is built via the
    // injected `buildUrl` (not a hand-built `/product/...` literal) so the assertion below proves
    // this component actually threads a real `buildUrl` through to the mapper (2026-09-15,
    // CodeRabbit finding, confirmed) — see the mocked `use-multi-site` above for the
    // distinguishing `/en-GB` prefix this proves against.
    mockSelectRecentlyViewedCard.mockImplementation((product, _formatPrice, buildUrl) =>
      product?.id === 'rec-2'
        ? null
        : {
            id: product?.id ?? '',
            href: buildUrl(`/product/${product?.id ?? ''}`),
            name: product?.name ?? '',
            primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
            currentPrice: undefined,
          },
    );

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, title: 'Recently Viewed' });

    expect(screen.getByTestId('zimm-recently-viewed-rail-stub')).toBeInTheDocument();
    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();

    // Build plan E1, edit 1: the fetch-effect early return for this recommender is gone —
    // getRecommendations now fires for it exactly like the other four recommenders already do.
    expect(mockGetRecommendations).toHaveBeenCalledWith(EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, undefined);

    // Branch's own mapping contract (not the rail's internals): the null-mapped product is
    // dropped, the surviving card carries the container-assigned `headingLevel`/`variation`, and
    // `title` is passed straight through from the caller's own prop — no `recommendations`
    // fallback.
    //
    // Renders twice, not once — `useRecentlyViewedRailVisibleCount`'s own `useMediaQuery` calls
    // add a second, legitimate render pass (matching this environment's SSR-safe
    // mount-with-fallback-then-resolve pattern). Not a regression in this branch's own logic;
    // asserting both calls agree is what actually matters here, not the raw count.
    expect(mockZimmRecentlyViewedRail.mock.calls.length).toBeGreaterThanOrEqual(1);
    const allCallsAgree = mockZimmRecentlyViewedRail.mock.calls.every(
      ([callProps]) => JSON.stringify(callProps) === JSON.stringify(mockZimmRecentlyViewedRail.mock.calls[0][0]),
    );
    expect(allCallsAgree).toBe(true);
    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
    expect(railProps.title).toBe('Recently Viewed');
    expect(railProps.cards).toHaveLength(1);
    expect(railProps.cards[0]).toMatchObject({
      id: 'rec-1',
      headingLevel: 'h3',
      variation: 'recentlyViewed',
    });
    // Proves buildUrl is genuinely threaded through to the mapper, not just accepted and ignored
    // — if this component stopped passing its third argument, the mock implementation above would
    // throw calling `undefined(...)` rather than silently produce an unprefixed href.
    expect(railProps.cards[0].href).toBe('/en-GB/product/rec-1');
  });

  test('any other recommender still calls getRecommendations and renders via ProductScroller, not the rail', () => {
    const mockGetRecommendations = vi.fn();
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: mockRecommendations,
      getZoneRecommendations: vi.fn(),
      getRecommendations: mockGetRecommendations,
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE });

    expect(screen.getByTestId('product-scroller-stub')).toBeInTheDocument();
    expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
    // Proves the RV branch is recommender-gated (would fail if the `if (recommender ===
    // PDP_RECENTLY_VIEWED)` check were accidentally dropped or widened) and that this sibling
    // recommender still fetches its own recommendations exactly as before.
    expect(mockGetRecommendations).toHaveBeenCalledWith(EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE, undefined);
  });

  test.each([
    ['recs is an empty array (AC 8: a real zero-history response)', buildRecentlyViewedRecommendations([])],
    ["recommendations has not resolved yet (useEinstein()'s own pre-fetch initial value)", []],
    ['recs is undefined on the recommendations object', { recommenderName: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED }],
  ])('renders null — no rail, no scroller — when %s', (_label, recommendationsValue) => {
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: recommendationsValue,
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    // Neither branch's component rendered — the component itself returns `null` here. Not
    // asserted via `container.toBeEmptyDOMElement()`: ChakraProvider always injects its own
    // internal `<span id="__chakra_env">` marker regardless of what this component renders, so
    // an empty-container check would be asserting on Chakra's own internals, not this
    // component's contract.
    expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
  });

  test('on the Cart route, renders null even when recs has items (Marcel, 2026-09-10: "no recently viewed on cart")', () => {
    // Deliberately non-empty recs — proves the Cart exclusion wins even when there IS real
    // Einstein data to show, not just the already-covered "nothing to show anyway" case above.
    // Cart has no Zimmermann page override of its own; its base page passes
    // recommender={EINSTEIN_RECOMMENDERS.CART_RECENTLY_VIEWED}, which resolves to the exact same
    // string as PDP_RECENTLY_VIEWED (see index.tsx's own isCartPage comment) — this recommender
    // value alone cannot distinguish the two, so this test renders at the real recommender value
    // used everywhere else in this suite and asserts the *route* is what suppresses it.
    const mockGetRecommendations = vi.fn();
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: buildRecentlyViewedRecommendations(mockRecentlyViewedProducts),
      getZoneRecommendations: vi.fn(),
      getRecommendations: mockGetRecommendations,
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED }, '/cart');

    expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
    // The fetch-effect now skips this call outright on the Cart route for this recommender
    // (CodeRabbit finding, fixed post-E1): previously fired unconditionally for every recommender,
    // Cart included, even though the render branch above always returns null for it here — one
    // harmless but wasted network call on a descoped surface. No longer fired at all.
    expect(mockGetRecommendations).not.toHaveBeenCalled();
  });

  // The See-Full-History link. jsdom resolves both `useMediaQuery` checks inside
  // `useRecentlyViewedRailVisibleCount` to `false` (see the `matchMedia` polyfill above), so
  // these fixtures are sized against `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base` (2) rather than
  // asserting anything about actual breakpoint switching — that's Chakra's own concern, not this
  // component's. What this component owns is purely "count vs threshold", which is
  // breakpoint-agnostic to test.
  test('See-Full-History link appears when available cards exceed the visible count at this breakpoint', () => {
    const ids = ['rec-1', 'rec-2', 'rec-3'];
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: buildRecentlyViewedRecommendations(
        ids.map((id) => ({ id, name: `Product ${id}` } as RecentlyViewedProduct)),
      ),
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });
    mockSelectRecentlyViewedCard.mockImplementation((product) => ({
      id: product?.id ?? '',
      href: `/product/${product?.id ?? ''}`,
      name: product?.name ?? '',
      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
      currentPrice: undefined,
    }));

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
    // Site/locale-prefixed via useMultiSite's buildUrl (mocked above to a non-default `/en-GB`
    // prefix) — the rail itself must never build this prefix, only the container.
    expect(railProps.seeAllHref).toBe('/en-GB/recently-viewed');
    expect(railProps.seeAllLabel).toBe('See Full History');
  });

  test('See-Full-History link is absent when available cards do not exceed the visible count at this breakpoint', () => {
    const ids = ['rec-1', 'rec-2'];
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: buildRecentlyViewedRecommendations(
        ids.map((id) => ({ id, name: `Product ${id}` } as RecentlyViewedProduct)),
      ),
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });
    mockSelectRecentlyViewedCard.mockImplementation((product) => ({
      id: product?.id ?? '',
      href: `/product/${product?.id ?? ''}`,
      name: product?.name ?? '',
      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
      currentPrice: undefined,
    }));

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
    expect(railProps.seeAllHref).toBeUndefined();
    expect(railProps.seeAllLabel).toBeUndefined();
  });
});

// PostBuild fix round, Fix 1/Fix 3 (2026-09-15). No pre-existing test in this file exercised the
// impression-tracking effect at all before this: `isOnScreen` was unconditionally stubbed `false`
// everywhere above (see that mock's own comment), so `if (isOnScreen && recommendations?.recs)`
// never ran its body in any existing test. Both tests below override it to `true` for one render
// via `mockUseIntersectionObserver.mockReturnValueOnce(true)` — a per-test override that leaves
// every test above completely unaffected (the mock's own default return stays `false`).
describe('RecommendedProducts — impression tracking (PostBuild fix round, Fix 1, 2026-09-15)', () => {
  test('Recently-Viewed: when every rec fails to map, no impression is reported at all', () => {
    // The exact bug Fix 1 closes: every one of this shopper's recently-viewed products fails
    // `selectRecentlyViewedCard`'s null-gate (e.g. no usable name/image), so the rail correctly
    // renders nothing — but before this fix, the impression-tracking effect ran ahead of that
    // filtering and still reported every raw id in `recommendations.recs` as "viewed": false signal
    // into Einstein/DataCloud's own feedback loop, with nothing on screen to indicate it happened.
    //
    // Verified directly, not just asserted (this codebase's own prove-don't-assert discipline —
    // matches recentlyViewed/index.test.tsx's own "all-stale-history gate" test): temporarily
    // reverting index.tsx's impression-tracking effect back to its pre-Fix-1 form (mapping
    // `recommendations.recs` directly, with no recommender branch) makes this exact test fail —
    // both `mockSendViewReco` and `mockSendViewRecommendations` are called, with the two ids that
    // never actually rendered — and restoring Fix 1 makes it pass again.
    const mockSendViewReco = vi.fn();
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: buildRecentlyViewedRecommendations(mockRecentlyViewedProducts),
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: mockSendViewReco,
    });
    // Both fixture products fail the mapper's own hard gate — the scenario Fix 1 exists for.
    mockSelectRecentlyViewedCard.mockReturnValue(null);
    mockUseIntersectionObserver.mockReturnValueOnce(true);

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, title: 'Recently Viewed' });

    // The mapping was attempted (proves this is "attempted and filtered", not "never ran") ...
    expect(mockSelectRecentlyViewedCard).toHaveBeenCalled();
    // ... but nothing survived it, so no impression was reported at all.
    expect(mockSendViewReco).not.toHaveBeenCalled();
    expect(mockSendViewRecommendations).not.toHaveBeenCalled();
  });

  test('any other recommender still reports the full raw recs list on impression, unchanged', () => {
    // Confirms Fix 1's recommender branch is genuinely additive, not a regression for the other
    // four recommenders: a non-Recently-Viewed recommender has no `selectRecentlyViewedCard`
    // filtering step in this component at all, so its reported id list must still be the full, raw
    // `recommendations.recs` mapped straight to `{ id }` — the exact pre-Fix-1 expression, now the
    // untouched `else` branch of index.tsx's own `ids` ternary.
    const mockSendViewReco = vi.fn();
    const otherRecommendations = {
      recommenderName: 'might-also-like-einstein',
      recoUUID: 'test-other-reco-uuid',
      displayMessage: 'You Might Also Like',
      recs: [
        { id: 'other-1', name: 'Recommended One' },
        { id: 'other-2', name: 'Recommended Two' },
      ],
    };
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: otherRecommendations,
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: mockSendViewReco,
    });
    mockUseIntersectionObserver.mockReturnValueOnce(true);

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE });

    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
    const expectedIds = [{ id: 'other-1' }, { id: 'other-2' }];
    const expectedRecoMeta = { recommenderName: 'might-also-like-einstein', __recoUUID: 'test-other-reco-uuid' };
    expect(mockSendViewReco).toHaveBeenCalledWith(expectedRecoMeta, expectedIds);
    expect(mockSendViewRecommendations).toHaveBeenCalledWith(expectedRecoMeta, expectedIds);
  });
});

